L = s.split('\n')
def ins_after(pred, para, label):
    idx = [i for i, x in enumerate(L) if pred(x)]
    assert len(idx) == 1, 'アンカー行が%d件: %s' % (len(idx), label)
    L.insert(idx[0] + 1, '')
